T = int(input())
for i in range(T):
	(n, k) = map(int, input().split())
	if n != 0:
		kk = k // 2
		nn = n + kk - 1
		nn = nn * (nn + 1)
		if k % 2 == 0:
			nn = (nn + n) % 1000000007
		else:
			nn = (nn + kk + n + kk) % 1000000007
		print(nn)
	else:
		k = k - 1
		k = k * (k + 1) % 1000000007
		print(k)
